import fs from 'node:fs/promises';
export const GUIDE_URI='plugin3://agent-guide';
export const GUIDE_PROMPT='plugin3-operating-guide';
export const GUIDE_INSTRUCTIONS='Plugin 3 v0.4.5: read plugin3_guide once per version (also resource plugin3://agent-guide). Batch independent reads and commands; absent optional instruction/lock paths are normal. native_patch uses the official engine with owned leases, durable hashes and uncertainty quarantine; use staged edits for huge files and rollback. Use adaptive read_batch, staged edits, durable jobs and agent mailboxes/leases. codex_threads reads local official Codex CLI history without inference; host-only chats are not included. agent_start prepares a handoff, not a running model. Windows force_terminate stops a held terminal tree and confirms cleanup; list_processes returns bounded CIM records with PID filter/pagination. Prefer job_cancel to Windows pipe Ctrl-C. browser_observe is enforced read-only with inline screenshots; browser_session has persistent Playwright locator and viewport input actions with partial receipts. Handles survive MCP reconnect, not broker restart. Never bypass host denials. Native VibeSpace QA requires verified official Tauri identity.';
const guideFile=new URL('../../../../3/skills/plugin3-native-work/SKILL.md',import.meta.url);
const upgradeGuide='\n\n## Verified 0.4.5 upgrade supplement\n\n- native_patch accepts official Codex add/update/move/delete hunks through stdin. Register a workspace and claim every source/destination first. Parent directories must exist; maximum 64 operations, 4 MiB payload and 16 MiB existing targets. Eight independent workspace workers, one writer per workspace. wait_ms defaults to 1000; when applying, poll edit_status. Native patches are not atomic and have no rollback backup. Inspect before/after hashes after a failure; uncertain workspaces block mutations. Use staged edit_plan/apply/rollback for huge files and guarded recovery.\n- codex_threads reads the installed official CLI history: list/read/turns/items only, with bounded output and pagination. It does not start/resume models or expose ChatGPT host-only conversations.\n- browser_session supports viewport CSS-pixel mouse_click/move/drag/wheel and keyboard_type/press alongside Playwright locators. browser_observe permits bounded inline screenshots but never input mutations. This is browser/WebView control, not an OS desktop mouse bridge.\n- Durable Windows PowerShell -Command jobs initialize UTF-8 stdout/stderr by default; preserve_console_encoding opts out. Prefer job_cancel to pipe Ctrl-C. force_terminate confirms a held terminal tree stops; list_processes uses real paginated CIM fields, with no command-line credential dump.\n- Eight agents/jobs/readers/edit workers are bounded capacity, not a guarantee of eight unrestricted writers. Follow repository locks, leases and hashes. Tool handles survive MCP reconnects, not broker restarts. Host denials, delegation and native-only app capabilities remain host-controlled.\n';
let cached;
export async function guideText(){return cached??=(await fs.readFile(guideFile,'utf8'))+upgradeGuide;}
export async function pluginGuide(args={}){if(!args||typeof args!=='object'||Array.isArray(args)||Object.keys(args).length)return {isError:true,content:[{type:'text',text:'plugin3_guide accepts an empty object'}]};return {isError:false,content:[{type:'text',text:await guideText()}]};}
